const mobileShowcase = `<section class="appShowcase" id="mobile-experience"><div class="wrap appShowcaseGrid"><div><div class="ey" style="color:var(--lime)">Interactive mobile experience</div><h2>Protection that stays simple when the system underneath is not.</h2><p class="lead">Try the core WITH. flows here without leaving the website. Start a Guardian journey, run a Safety Countdown, explore nearby help or review your Trusted Circle.</p><div class="appPoints"><div class="appPoint"><b>01</b><p><strong>Ready before you leave.</strong><br>Permissions, people and connection are visible before protection starts.</p></div><div class="appPoint"><b>02</b><p><strong>Focused while active.</strong><br>The interface shows only the status and actions that matter.</p></div><div class="appPoint"><b>03</b><p><strong>Honest about the prototype.</strong><br>No live tracking, dispatch or emergency response is connected.</p></div></div><a class="btn safe" href="/app">Open the full-screen app preview</a></div><div class="phoneEmbed"><iframe src="/app?embed=1" title="Interactive WITH. mobile app preview" loading="lazy"></iframe></div></div></section>`;

